import json
import pandas as pd

SOURCES = [
    ("source_a", "/data/source_a/users.json"),
    ("source_b", "/data/source_b/users.csv"),
    ("source_c", "/data/source_c/users.parquet"),
]

# per-source mapping: unified_field -> actual column name
MAPPING = {
    "source_a": {"user_id": "id", "name": "full_name", "email": "email",
                 "created_date": "registration_date", "status": "status"},
    "source_b": {"user_id": "user_id", "name": "name", "email": "email_address",
                 "created_date": "created_at", "status": "is_active"},
    "source_c": {"user_id": "userId", "name": "userName", "email": "email",
                 "created_date": "joined", "status": "active"},
}

TRUE_VALS = {"true", "1", "yes", "y", "active", "t"}
FALSE_VALS = {"false", "0", "no", "n", "inactive", "f"}


def norm_status(v):
    if v is None or (isinstance(v, float) and pd.isna(v)):
        return None
    if isinstance(v, bool):
        return "active" if v else "inactive"
    s = str(v).strip()
    if s == "" or s.lower() in {"nan", "none", "null", "nat"}:
        return None
    if s.lower() in TRUE_VALS:
        return "active"
    if s.lower() in FALSE_VALS:
        return "inactive"
    return s


def norm_date(v):
    if v is None:
        return None
    if isinstance(v, float) and pd.isna(v):
        return None
    s = str(v).strip()
    if s == "" or s.lower() in {"nan", "none", "null", "nat"}:
        return None
    ts = pd.to_datetime(s, errors="coerce")
    if pd.isna(ts):
        return s
    return ts.strftime("%Y-%m-%d")


def norm_id(v):
    if v is None or (isinstance(v, float) and pd.isna(v)):
        return None
    try:
        return int(float(str(v).strip()))
    except (ValueError, TypeError):
        return None


def norm_text(v):
    if v is None or (isinstance(v, float) and pd.isna(v)):
        return None
    s = str(v).strip()
    if s == "" or s.lower() in {"nan", "none", "null"}:
        return None
    return s


def load_sources():
    data = {}
    with open(SOURCES[0][1]) as f:
        payload = json.load(f)
    if isinstance(payload, dict):
        payload = next((v for v in payload.values() if isinstance(v, list)), [])
    data["source_a"] = pd.DataFrame(payload)
    data["source_b"] = pd.read_csv(SOURCES[1][1], dtype=str, keep_default_na=False)
    data["source_c"] = pd.read_parquet(SOURCES[2][1])
    return data


def normalize_frame(source, df):
    m = MAPPING[source]
    records = {}
    for _, row in df.iterrows():
        uid = norm_id(row.get(m["user_id"]))
        if uid is None:
            continue
        rec = {
            "user_id": uid,
            "name": norm_text(row.get(m["name"])),
            "email": norm_text(row.get(m["email"])),
            "created_date": norm_date(row.get(m["created_date"])),
            "status": norm_status(row.get(m["status"])),
        }
        prev = records.get(uid)
        if prev is None:
            records[uid] = rec
        else:
            for k, v in rec.items():
                if prev.get(k) is None and v is not None:
                    prev[k] = v
    return records


def main():
    frames = load_sources()
    per_source = {s: normalize_frame(s, frames[s]) for s, _ in SOURCES}

    all_ids = sorted({uid for recs in per_source.values() for uid in recs})
    fields = ["name", "email", "created_date", "status"]

    merged, conflicts = [], []
    for uid in all_ids:
        row = {"user_id": uid}
        for field in fields:
            values = {}
            for src, _ in SOURCES:
                rec = per_source[src].get(uid)
                if rec is not None and rec.get(field) is not None:
                    values[src] = rec[field]
            selected = next((values[s] for s, _ in SOURCES if s in values), None)
            row[field] = selected
            if len(set(values.values())) > 1:
                conflicts.append({
                    "user_id": uid,
                    "field": field,
                    "values": values,
                    "selected": selected,
                })
        merged.append(row)

    out = pd.DataFrame(merged, columns=["user_id", "name", "email", "created_date", "status"])
    out["user_id"] = out["user_id"].astype("int64")
    for c in ["name", "email", "created_date", "status"]:
        out[c] = out[c].astype(object)
    out.to_parquet("/app/merged_users.parquet", index=False)

    report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
    with open("/app/conflicts.json", "w") as f:
        json.dump(report, f, indent=2)

    print(out.to_string())
    print(json.dumps(report, indent=2))


if __name__ == "__main__":
    main()
